CREATE TABLE IF NOT EXISTS `ai_pricing_log` (`id` BIGINT NOT NULL AUTO_INCREMENT, `user_id` BIGINT NOT NULL, `item_name` VARCHAR(100) NOT NULL, `item_category` VARCHAR(50) NOT NULL, `condition_level` TINYINT NOT NULL, `original_price` DECIMAL(12,2) NOT NULL, `suggested_price` DECIMAL(12,2) NOT NULL, `depreciation_rate` DECIMAL(6,4) NOT NULL, `pricing_reason` VARCHAR(500) NOT NULL, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `idx_pricing_user` (`user_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
